    /*
     * Add to the Datasets
     * 
     * @param	parentID	UUID
     * @param	addTo		childType
     * @return	Forecast
     */
    public Forecast addToDatasets( UUID parentId, DataSet addTo ) {
	    LOGGER.info("handling AssignDatasetsToForecastEvent - " );
	    
	    Forecast parentEntity = repository.findById(parentId).get();
	    DataSet child = registry.project( DataSet.class, addTo.getDataSetId());
	    
	    parentEntity.getDatasets().add( child );

	    // ------------------------------------------
    	// save 
    	// ------------------------------------------ 
	    repository.save(parentEntity);
        
	    return parentEntity;
    }
    

    /*
     * Remove from the Datasets
     * 
     * @param	parentID	UUID
     * @param	removeFrom	childType
     * @return	Forecast
     */
	public Forecast removeFromDatasets( UUID parentId, DataSet removeFrom ) {
	    LOGGER.info("handling RemoveDatasetsFromForecastEvent " );
	
	    Forecast parentEntity = repository.findById(parentId).get();
	    DataSet child = registry.project( DataSet.class, removeFrom.getDataSetId());
	    
	    parentEntity.getDatasets().remove( child );
	
	    // ------------------------------------------
		// save
		// ------------------------------------------ 
	    update(parentEntity);
	    
	    return parentEntity;
	}



    /**
     * Method to retrieve the Forecast via an FindForecastQuery
     * @return 	query	FindForecastQuery
     */
    @SuppressWarnings("unused")
    public Forecast find( UUID id ) {
    	LOGGER.info("handling find using " + id.toString() );
    	try {
    		return repository.findById(id).get();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find a Forecast - {0}", exc.getMessage() );
    	}
    	return null;
    }
    
    /**
     * Method to retrieve a collection of all Forecasts
     *
     * @param	query	FindAllForecastQuery 
     * @return 	List<Forecast> 
     */
    @SuppressWarnings("unused")
    public List<Forecast> findAll( FindAllForecastQuery query ) {
    	LOGGER.info("handling findAll using " + query.toString() );
    	try {
    		return repository.findAll();
    	}
    	catch( IllegalArgumentException exc ) {
    		LOGGER.warn( "Failed to find all Forecast - {0}", exc.getMessage() );
    	}
    	return null;
    }


